types.prepare:
const task = fields.task === "find" || fields.task === "name" ? fields.task : "line";
if (task !== "line") {
  const s = /^[a-h][1-8]$/.test(String(fields.square ?? "").toLowerCase()) ? String(fields.square).toLowerCase() : "e4";
  return {
    view: { task, prompt: fields.prompt ?? "", flip: !!fields.flip, square: task === "name" ? s : "" },
    key: { task, square: s },
  };
}
function fnv(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, "0");
}
function seal(text, k) {
  let out = "", h = k;
  for (let i = 0; i < text.length; i++) { h = fnv(h + i); out += (text.charCodeAt(i) ^ parseInt(h.slice(0, 2), 16)).toString(16).padStart(2, "0"); }
  return out;
}
const moves = (fields.moves ?? []).map((m) => String(m).toLowerCase().trim()).filter(Boolean);
const auto = Math.max(0, Math.floor(Number(fields.auto ?? 0)) || 0);
const alts = Array.isArray(fields.alts) ? fields.alts : [];
const salt = fnv(String(rng.next()) + String(fields.fen ?? ""));
const steps = [];
for (let i = auto, n = 0; i < moves.length; i += 2, n++) {
  const ok = [moves[i], ...(alts[n] ?? []).map((x) => String(x).toLowerCase())];
  const reply = moves[i + 1] ?? "";
  steps.push({ h: ok.map((x) => fnv(`${salt}|h|${n}|${x}`)), r: reply ? seal(reply, `${salt}|k|${n}|${moves[i]}`) : "" });
}
return {
  view: { task, prompt: fields.prompt ?? "", fen: String(fields.fen ?? "").trim(), auto: moves.slice(0, auto), steps, salt },
  key: { task, moves, auto, alts, theme: fields.theme ?? "", rating: fields.rating ?? null, explanation: fields.explanation ?? "" },
};

template.css:
/* Chess puzzle (multi-move lines and the board squares), in the Etude 3 look (Design Lab round 06): cartoon pieces on a fixed green board,
   the question above it, and an answer column beside it once graded. Text follows the app's theme. */
:root { --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --E: cubic-bezier(.2, .8, .2, 1); }
.ch { display: flex; flex-direction: column; align-items: center; gap: 16px; }
.ch-head { display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center; }
.ch-prompt { font: 400 28px/1.18 var(--serif); color: var(--foreground); }
.ch-prompt p { margin: 0; }
.ch-turn { display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--muted-foreground); }
.ch-turn .dot { width: 12px; height: 12px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--foreground); }
.ch-turn .dot.w { background: #fffdf5; }
.ch-turn .dot.b { background: #2a2520; }
.ch-main { display: flex; flex-direction: column; align-items: center; gap: 16px; width: 100%; }

/* The board keeps its own colours in every theme, like a real board; a1 is dark. */
.ch-board { position: relative; width: min(100%, 440px, calc(var(--etude-screen-height, 9999px) - 190px)); min-width: 240px;
  aspect-ratio: 1; border-radius: 6px; flex: none; outline: none; touch-action: none; user-select: none; -webkit-user-select: none;
  --lt: #efe4c8; --lt: light-dark(#eeeeeb, #efe4c8); --dk: #8fae86; --sh: light-dark(rgba(0, 0, 0, .07), rgba(0, 0, 0, .45));
  box-shadow: 0 10px 26px var(--sh); box-shadow: 0 0 0 1px light-dark(var(--border), transparent), 0 10px 26px var(--sh); }
.ch-sqs { position: absolute; inset: 0; display: grid; grid-template: repeat(8, 1fr) / repeat(8, 1fr); border-radius: inherit; overflow: hidden; }
.sq { position: relative; background: var(--lt); }
.sq.d { background: var(--dk); }
/* The last move and the mate: one warm yellow over both squares (like lichess), never another green.
   The square it went to is a touch stronger, so the move reads toward where the piece stands now. */
.sq::before { content: ""; position: absolute; inset: 0; background: rgba(247, 196, 52, 0); pointer-events: none; }
.sq.mv::before, .sq.good::before { background: rgba(247, 196, 52, .6); }
.sq.mv.to::before, .sq.good.to::before { background: rgba(247, 196, 52, .75); }
/* Green shows through more, so the dark squares take more yellow to stay warm. */
.sq.d.mv::before, .sq.d.good::before { background: rgba(247, 196, 52, .72); }
.sq.d.mv.to::before, .sq.d.good.to::before { background: rgba(247, 196, 52, .82); }
.sq.sel { box-shadow: inset 0 0 0 4px #f2b632; }
.sq.cur { box-shadow: inset 0 0 0 3px var(--ring, #f2b632); }
.sq.sel.cur { box-shadow: inset 0 0 0 4px #f2b632, inset 0 0 0 7px var(--ring, #f2b632); }
.sq.dot::after { content: ""; position: absolute; left: 37%; top: 37%; width: 26%; height: 26%; border-radius: 50%; background: rgba(30, 40, 20, .28); }
.sq.cap::after { content: ""; position: absolute; inset: 0; box-shadow: inset 0 0 0 5px rgba(30, 40, 20, .28); }
.sq.hov { box-shadow: inset 0 0 0 4px rgba(30, 40, 20, .32); }
.sq i { position: absolute; font: 600 10px/1 var(--font-sans); font-style: normal; opacity: .78; pointer-events: none; }
.sq.l i { color: #5d7d55; } .sq.d i { color: #f7f4e8; }
.sq .rk { left: 3px; top: 3px; } .sq .fl { right: 3px; bottom: 2px; }
.ch-board:focus-visible { box-shadow: 0 0 0 2px var(--ring, #f2b632), 0 10px 26px var(--sh); }

.ch-pcs { position: absolute; inset: 0; pointer-events: none; }
.pc { position: absolute; width: 12.5%; height: 12.5%;
  transition-property: left, top, opacity, transform; transition-duration: 260ms; transition-timing-function: cubic-bezier(.3, .7, .2, 1); }
.pc img { position: absolute; left: 50%; top: 50%; width: auto; display: block; transform: translate(-50%, -50%);
  filter: drop-shadow(0 2px 1.5px rgba(30, 25, 15, .3)); transition: transform .15s; }
.pc.up img { transform: translate(-50%, -57%) scale(1.04); }
.pc.drag { z-index: 5; transition-property: none; }
.pc.drag img { transform: translate(-50%, -54%) scale(1.12); filter: drop-shadow(0 8px 6px rgba(30, 25, 15, .32)); }
.pc.gone { opacity: 0; transform: scale(.6); }
.ch-over { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }
.ch-over .tried { stroke: var(--danger); stroke-width: 16; stroke-linecap: round; opacity: .82; animation: ch-fade .3s var(--E) backwards; }
#ch-ah path { fill: var(--danger); }
.ch-over .mated { fill: none; stroke: var(--danger); stroke-width: 7; animation: ch-ring .45s var(--E) backwards; }
@keyframes ch-ring { from { r: 20; opacity: 0; } }
@keyframes ch-fade { from { opacity: 0; } }

.ch-hint { margin: 0; font-size: 15px; color: var(--muted-foreground); text-align: center; min-height: 1.6em; }
.ch-hint b { color: var(--foreground); font-family: var(--serif); font-size: 17px; font-weight: 600; }
.ch-undo { all: unset; cursor: pointer; color: var(--foreground); text-decoration: underline; text-decoration-color: color-mix(in oklab, var(--foreground) 30%, transparent); text-underline-offset: 3px; }
.ch-undo kbd { font-size: 11px; margin-left: 2px; }

/* Graded: the question goes, the board moves left and the answer stands beside it. */
[data-mode="result"] .ch-head { display: none; }
[data-mode="result"] .ch-main { flex-direction: row; justify-content: center; align-items: center; gap: 36px; }
[data-mode="result"] .ch-board { width: min(56%, 420px); min-width: 0; }
/* No drop shadow once graded: the frame ends just under the board and would cut it into a grey edge. */
[data-mode="result"] .ch-board { box-shadow: none; box-shadow: 0 0 0 1px light-dark(var(--border), transparent); }
.ch-info { flex: 0 1 300px; min-width: 0; text-align: left; }
.ch-tag { font-size: 12px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--muted-foreground); }
.ch-tag.ok { color: var(--success); }
.ch-san { font: 400 40px/1.1 var(--serif); color: var(--foreground); margin-top: 6px; }
.ch-yours { margin: 12px 0 0; font-size: 15px; line-height: 1.5; color: var(--danger); }
.ch-yours b { font-family: var(--serif); font-size: 16px; }
.ch-expl { margin-top: 12px; font-size: 16px; line-height: 1.55; color: var(--muted-foreground); }
.ch-expl p { margin: 0 0 .6em; } .ch-expl p:last-child { margin: 0; }
.ch-expl strong { color: var(--foreground); }
.ch-ghost { display: flex !important; flex-direction: column; align-items: center; gap: 6px; text-align: center; position: fixed; margin: 0; pointer-events: none; z-index: 20; }
.ch-ghost .ch-prompt p { margin: 0; }

@media (max-width: 600px) {
  .ch-prompt { font-size: 24px; }
  [data-mode="result"] .ch-main { flex-direction: column; gap: 16px; }
  [data-mode="result"] .ch-board { width: min(100%, 420px); }
  .ch-info { flex: none; width: 100%; text-align: center; }
}
@media (prefers-reduced-motion: reduce) {
  .pc, .pc img { transition: none !important; }
  .ch-over .tried, .ch-over .mated { animation: none; }
}

/* Lines: the moves of the solution, clickable to step through; ← → step too. */
.ch-line { margin-top: 8px; font: 400 21px/1.55 var(--serif); color: var(--foreground); }
.ch-line .g { white-space: nowrap; }
.ch-line .n { color: var(--muted-foreground); font-size: 16px; margin-right: 3px; font-family: var(--font-sans); }
.ch-line .m { all: unset; cursor: pointer; padding: 0 3px; border-radius: 5px; }
.ch-line .m:hover { background: color-mix(in oklab, var(--foreground) 8%, transparent); }
.ch-line .m.on { background: rgba(247, 196, 52, .32); }
.ch-line .m.pre { color: var(--muted-foreground); }
.ch-meta { margin-top: 10px; font-size: 13px; color: var(--muted-foreground); }
.ch-meta:empty { display: none; }
.sq.bad::before { background: rgba(220, 70, 60, .55) !important; }
.ch-give { margin-left: 6px; color: var(--muted-foreground); }

/* The square tasks: a bare board, the square to find in big type or a highlighted square to name. */
.is-squares .ch-prompt strong { font-size: 1.5em; }
.sq.ask::before { background: rgba(247, 196, 52, .85); }
.sq .nm { left: 50%; top: 50%; transform: translate(-50%, -50%); font-size: 11px; opacity: .55; }
.ch-name input { width: 96px; text-align: center; font: 400 26px/1.2 var(--serif); padding: 6px 10px; }
.is-squares .ch-line { font-size: 40px; }

grader.code:
if (key.task === "find" || key.task === "name") {
  const a = String(answer ?? "").toLowerCase().trim();
  const ok = a === key.square;
  return { score: ok ? 1 : 0, feedback: ok ? undefined : a ? `${a} isn't ${key.square}.` : "No square given.", details: { square: a } };
}
const played = (Array.isArray(answer) ? answer : Array.isArray(answer?.moves) ? answer.moves : []).map((m) => String(m).toLowerCase());
const sol = [];
for (let i = key.auto; i < key.moves.length; i += 2) sol.push(key.moves[i]);
let right = 0, solved = false;
for (let n = 0; n < sol.length; n++) {
  const m = played[n];
  if (!m) break;
  if (m === sol[n]) { right++; if (n === sol.length - 1) solved = true; continue; }
  if ((key.alts?.[n] ?? []).map(String).includes(m)) { right++; solved = true; }
  break;
}
const gave = !!answer?.gave;
const feedback = solved ? undefined : gave ? "Solution shown." : played.length > right ? (sol.length > 1 ? `Move ${right + 1} of ${sol.length} went wrong.` : "That's not the move.") : "Not finished.";
return { score: solved ? 1 : 0, feedback, details: { right, steps: sol.length, gave } };

types.demo:
// An example answer for watch mode: the solution's moves, or the square.
if (key.task === "find" || key.task === "name") return key.square;
const out = [];
for (let i = key.auto; i < key.moves.length; i += 2) out.push(key.moves[i]);
return { moves: out, gave: false };
